package co.kr.badara.campsitejournal.test;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.os.*;import android.webkit.*;import java.util.concurrent.*;
/** Local WebView fixture: no connection key, platform login or production records. */
public class ThemeTest extends Instrumentation {
 private String script;private Activity activity;private WebView web;private int original;
 @Override public void onCreate(Bundle args){super.onCreate(args);script=new String(android.util.Base64.decode(args.getString("themeScript"),android.util.Base64.DEFAULT),java.nio.charset.StandardCharsets.UTF_8);start();}
 private String js(String value)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] out={null};runOnMainSync(()->web.evaluateJavascript(value,r->{out[0]=r;done.countDown();}));if(!done.await(10,TimeUnit.SECONDS))throw new AssertionError("JS timeout");return out[0];}
 private void night(boolean dark){runOnMainSync(()->{Configuration config=new Configuration(activity.getResources().getConfiguration());config.uiMode=(config.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);activity.getResources().updateConfiguration(config,activity.getResources().getDisplayMetrics());activity.onConfigurationChanged(config);});}
 private void expect(String value)throws Exception{for(int i=0;i<40;i++){if(value.equals(js("document.documentElement.dataset.campTheme")))return;Thread.sleep(100);}throw new AssertionError("Expected "+value+" got "+js("document.documentElement.dataset.campTheme"));}
 @Override public void onStart(){Bundle result=new Bundle();try{activity=startActivitySync(new Intent().setClassName("co.kr.badara.campsitejournal","co.kr.badara.campsitejournal.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));original=activity.getResources().getConfiguration().uiMode;runOnMainSync(()->{try{java.lang.reflect.Field field=activity.getClass().getDeclaredField("web");field.setAccessible(true);WebView old=(WebView)field.get(activity);if(old!=null)old.destroy();web=new WebView(activity);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);Class<?> bridge=Class.forName("co.kr.badara.campsitejournal.MainActivity$PhotoPickerBridge");java.lang.reflect.Constructor<?> constructor=bridge.getDeclaredConstructor(activity.getClass(),boolean.class);constructor.setAccessible(true);web.addJavascriptInterface(constructor.newInstance(activity,false),"CampsiteJournalNative");field.set(activity,web);activity.setContentView(web);web.loadDataWithBaseURL("https://camp-theme.test/","<script>"+script+"</script>","text/html","UTF-8",null);}catch(Exception e){throw new RuntimeException(e);}});night(true);expect("\"dark\"");if(!"\"light\"".equals(js("matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'")))throw new AssertionError("Fixture should retain the fixed-light Android app theme");js("CampTheme.setMode('light')");night(false);night(true);expect("\"light\"");js("CampTheme.setMode('system')");expect("\"dark\"");night(false);expect("\"light\"");result.putString("result","PASS");result.putString("theme","native OS preference overrides fixed-light WebView; manual mode preserved; changes applied without reload");finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("result",error.toString());finish(Activity.RESULT_CANCELED,result);}finally{if(activity!=null){night((original&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);runOnMainSync(()->activity.finish());}}}
}
